private void priLoadFilesFound()
        {
            string sPathLOG = tbxPathSource.Text;
            DateTime dtDateInitial = dtpDateInitial.Value.Date;
            DateTime dtDateFinal = dtpDateFinal.Value.Date.AddDays(1).AddTicks(-1);

            if (!Directory.Exists(sPathLOG))
            {
                MessageBox.Show(gasMessage[2], Text, MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (dtDateInitial > dtDateFinal)
            {
                MessageBox.Show(gasMessage[3], Text, MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            List<string> asSelectedPaths = priGetSelectedFolderPaths();
            if (asSelectedPaths.Count == 0)
            {
                MessageBox.Show(gasMessage[4], Text, MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            try
            {
                Cursor = Cursors.WaitCursor;
                lvwFilesFound.BeginUpdate();
                lvwFilesFound.Items.Clear();

                HashSet<string> asFilePaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                List<FileInfo> aeFiles = new List<FileInfo>();

                foreach (string sPath in asSelectedPaths)
                {
                    try
                    {
                        foreach (string sFile in Directory.GetFiles(
                            sPath,
                            "*.log",
                            System.IO.SearchOption.TopDirectoryOnly))
                        {
                            FileInfo eFileInfo = new FileInfo(sFile);

                            if (eFileInfo.LastWriteTime < dtDateInitial || eFileInfo.LastWriteTime > dtDateFinal)
                                continue;

                            if (asFilePaths.Add(eFileInfo.FullName))
                                aeFiles.Add(eFileInfo);
                        }
                    }
                    catch (UnauthorizedAccessException)
                    {
                        //Continua nas demais pastas
                    }
                    catch (IOException)
                    {
                        //Continua nas demais pastas
                    }
                }

                gbUpdatingFileCheck = true;

                foreach (FileInfo eFileInfo in aeFiles.OrderBy(eFile => eFile.DirectoryName).ThenBy(eFile => eFile.Name))
                {
                    ListViewItem eItem = new ListViewItem(string.Empty);
                    eItem.SubItems.Add(eFileInfo.Name);
                    eItem.SubItems.Add(priGetRelativeDirectory(sPathLOG, eFileInfo.DirectoryName));
                    eItem.SubItems.Add(eFileInfo.LastWriteTime.ToString("dd/MM/yyyy HH:mm:ss"));
                    eItem.SubItems.Add(priFormatFileSize(eFileInfo.Length));
                    eItem.SubItems.Add(gasStatus[0]);
                    eItem.Tag = eFileInfo;
                    eItem.ToolTipText = eFileInfo.FullName;
                    eItem.Checked = true;
                    lvwFilesFound.Items.Add(eItem);
                }
            }
            catch (Exception ex)
            {
                Utilities.Log(ex.Message + ex.StackTrace, @"C:\Gemba\LOG\" + Utilities.GetApplicationName(), "Log ");
            }
            finally
            {
                gbUpdatingFileCheck = false;
                lvwFilesFound.EndUpdate();
                Cursor = Cursors.Default;
                priUpdateSummary();
            }

            if (lvwFilesFound.Items.Count == 0)
                MessageBox.Show(gasMessage[5], Text, MessageBoxButtons.OK, MessageBoxIcon.Information);
        }

