private IEnumerable<ExceptionOccurrenceData> priReadExceptionLogFiles(string ksLogPath,
            IEnumerable<string> kasSelectedFolders, DateTime keStartDate, DateTime keEndDate,
            out int kiFilesRead)
        {
            List<ExceptionOccurrenceData> aeOccurrences = new List<ExceptionOccurrenceData>();
            List<KeyValuePair<DateTime, string>> aeLogFiles = new List<KeyValuePair<DateTime, string>>();
            kiFilesRead = 0;

            foreach (string sSelectedFolder in kasSelectedFolders.Distinct(StringComparer.OrdinalIgnoreCase))
            {
                string[] asLogFiles;

                try
                {
                    asLogFiles = Directory.GetFiles(sSelectedFolder, "*.log", SearchOption.TopDirectoryOnly);
                }
                catch (IOException)
                {
                    continue;
                }
                catch (UnauthorizedAccessException)
                {
                    continue;
                }

                foreach (string sLogFile in asLogFiles)
                {
                    Match eFileMatch = Regex.Match(Path.GetFileName(sLogFile),
                        @"(?<date>\d{4}_\d{2}_\d{2})\.log$", RegexOptions.IgnoreCase);
                    DateTime eFileDate;

                    if (!eFileMatch.Success ||
                        !DateTime.TryParseExact(eFileMatch.Groups["date"].Value, "yyyy_MM_dd",
                            CultureInfo.InvariantCulture, DateTimeStyles.None, out eFileDate) ||
                        eFileDate.Date < keStartDate || eFileDate.Date > keEndDate)
                    {
                        continue;
                    }

                    aeLogFiles.Add(new KeyValuePair<DateTime, string>(eFileDate, sLogFile));
                }
            }

            foreach (KeyValuePair<DateTime, string> eLogFile in aeLogFiles.OrderBy(file => file.Key))
            {
                try
                {
                    string sProgram = priGetExceptionSourceProgram(ksLogPath, eLogFile.Value);
                    priReadExceptionLogFile(eLogFile.Value, sProgram, aeOccurrences);
                    kiFilesRead++;
                }
                catch (IOException ex)
                {
                    Utilities.Log(ex.Message + ex.StackTrace, @"C:\Gemba\LOG\" + Utilities.GetApplicationName(), "Log ");
                }
                catch (UnauthorizedAccessException ex)
                {
                    Utilities.Log(ex.Message + ex.StackTrace, @"C:\Gemba\LOG\" + Utilities.GetApplicationName(), "Log ");
                }
            }

            return aeOccurrences;
        }

private void priReadExceptionLogFile(string ksLogFile, string ksProgram,
            List<ExceptionOccurrenceData> kaeOccurrences)
        {
            DateTime eCurrentDate = DateTime.MinValue;
            StringBuilder sCurrentEntry = null;

            foreach (string sLine in File.ReadLines(ksLogFile))
            {
                DateTime eLineDate;

                if (priTryGetLogDate(sLine, out eLineDate))
                {
                    priAddExceptionOccurrence(kaeOccurrences, eCurrentDate, sCurrentEntry, ksProgram);
                    eCurrentDate = eLineDate;
                    sCurrentEntry = new StringBuilder(priGetExceptionLogMessage(sLine));
                    continue;
                }

                if (sCurrentEntry != null && !string.IsNullOrWhiteSpace(sLine))
                {
                    sCurrentEntry.AppendLine();
                    sCurrentEntry.Append(sLine.TrimEnd());
                }
            }

            priAddExceptionOccurrence(kaeOccurrences, eCurrentDate, sCurrentEntry, ksProgram);
        }

private string priGetExceptionLogMessage(string ksLine)
        {
            const string sMessageMarker = "-->:";
            int iMessagePosition = ksLine.IndexOf(sMessageMarker, StringComparison.Ordinal);
            return iMessagePosition >= 0 ? ksLine.Substring(iMessagePosition + sMessageMarker.Length).Trim() : ksLine.Trim();
        }

private void priAddExceptionOccurrence(List<ExceptionOccurrenceData> kaeOccurrences,
            DateTime keDate, StringBuilder ksEntry, string ksProgram)
        {
            if (ksEntry == null || keDate == DateTime.MinValue)
            {
                return;
            }

            string sDetails = ksEntry.ToString().Trim();
            ExceptionOccurrenceType? eType = priClassifyExceptionOccurrence(sDetails);

            if (!eType.HasValue)
            {
                return;
            }

            string sModule;
            string sFunction;
            priGetExceptionOrigin(sDetails, ksProgram, out sModule, out sFunction);

            kaeOccurrences.Add(new ExceptionOccurrenceData
            {
                Date = keDate,
                Type = eType.Value,
                Module = sModule,
                Program = ksProgram,
                Function = sFunction,
                Message = priGetExceptionSummaryMessage(sDetails),
                Details = sDetails,
                Production = priGetExceptionReferenceNumber(sDetails, "producao"),
                Batch = priGetExceptionReferenceNumber(sDetails, "batelada")
            });
        }

private List<LogZipPackage> priCreateZipPackages(List<ListViewItem> kaeItems, string ksPathSource, string ksPathDestination)
        {
            List<FileInfo> aeFiles = kaeItems
                .Select(eItem => (FileInfo)eItem.Tag)
                .OrderBy(eFileInfo => eFileInfo.FullName)
                .ToList();

            //Gera um único ZIP quando a opção estiver marcada
            if (chbSingleFile.Checked)
            {
                string sZipName = string.Format("C000.00.LOG({0})V0.0.0.0.zip", DateTime.Today.ToString("yyyy_MM_dd", CultureInfo.InvariantCulture));

                return new List<LogZipPackage>
                {
                    new LogZipPackage(
                        ksPathSource,
                        ksPathDestination,
                        aeFiles,
                        sZipName)
                };
            }

            return aeFiles
                .GroupBy(
                    eFileInfo => priGetZipSourcePath(ksPathSource, eFileInfo),
                    StringComparer.OrdinalIgnoreCase)
                .Select(eGroup => new LogZipPackage(
                    eGroup.Key,
                    ksPathDestination,
                    eGroup.ToList()))
                .OrderBy(ePackage => ePackage.ZipName)
                .ToList();
        }

